CREATE TABLE iam_accounts (id VARCHAR(36) PRIMARY KEY, username VARCHAR(64) NOT NULL UNIQUE, display_name VARCHAR(128) NOT NULL, status VARCHAR(16) NOT NULL CHECK(status IN ('active','disabled')), must_change_password BOOLEAN NOT NULL, security_revision BIGINT NOT NULL, failed_attempts INTEGER NOT NULL, locked_until TIMESTAMPTZ NULL, version BIGINT NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE iam_local_credentials (account_id VARCHAR(36) PRIMARY KEY REFERENCES iam_accounts(id) ON DELETE CASCADE, password_hash TEXT NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE iam_roles (id VARCHAR(36) PRIMARY KEY, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(128) NOT NULL, description TEXT NOT NULL, active BOOLEAN NOT NULL, archived BOOLEAN NOT NULL, system BOOLEAN NOT NULL, version BIGINT NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE iam_account_roles (account_id VARCHAR(36) NOT NULL REFERENCES iam_accounts(id) ON DELETE CASCADE, role_id VARCHAR(36) NOT NULL REFERENCES iam_roles(id) ON DELETE CASCADE, active BOOLEAN NOT NULL, updated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY(account_id,role_id));
CREATE TABLE iam_role_permissions (role_id VARCHAR(36) NOT NULL REFERENCES iam_roles(id) ON DELETE CASCADE, permission_key VARCHAR(160) NOT NULL, active BOOLEAN NOT NULL, updated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY(role_id,permission_key));
CREATE TABLE iam_sessions (id_hash BYTEA PRIMARY KEY, account_id VARCHAR(36) NOT NULL REFERENCES iam_accounts(id) ON DELETE CASCADE, csrf_hash BYTEA NOT NULL, security_revision BIGINT NOT NULL, created_at TIMESTAMPTZ NOT NULL, last_seen_at TIMESTAMPTZ NOT NULL, idle_expires_at TIMESTAMPTZ NOT NULL, absolute_expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ NULL);
CREATE INDEX ix_iam_sessions_account ON iam_sessions(account_id);
